/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, I, Mul, Rational, isEulerJacobiPseudoprime, isExtraStrongLucasPrp, isFermatPseudoprime, isGaussianPrime, isMersennePrime, isSquare, isUnsolved, isprime, mr, prothTest } from '../../src';
import { sympyStr } from '../sympy-str';

describe("doctests of sympy.ntheory.primetest", () => {
  it("is_mersenne_prime(6)", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("is_mersenne_prime(127)", () => {
    expect(sympyStr(isMersennePrime(Rational.of(127n, 1n, { gcd: 1n })))).toBe('True');
  });
  it("isprime(13)", () => {
    expect(sympyStr(isprime(Rational.of(13n, 1n, { gcd: 1n })))).toBe('True');
  });
  it("isprime(15)", () => {
    expect(sympyStr(isprime(Rational.of(15n, 1n, { gcd: 1n })))).toBe('False');
  });
  it("near_int == int(near_int)", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("n % 1 == 0", () => {
    expect(sympyStr(Rational.of(0n, 1n, { gcd: 1n }).equals(Rational.of(0n, 1n, { gcd: 1n })))).toBe('True');
  });
  it("n % 1 == 0 (2)", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("is_square(25)", () => {
    expect(sympyStr(isSquare(Rational.of(25n, 1n, { gcd: 1n })))).toBe('True');
  });
  it("is_square(2)", () => {
    expect(sympyStr(isSquare(Rational.of(2n, 1n, { gcd: 1n })))).toBe('False');
  });
  it("mr(1373651, [2, 3])", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
  it("mr(479001599, [31, 73])", () => {
    expect(sympyStr(mr(Rational.of(479001599n, 1n, { gcd: 1n }), [31, 73]))).toBe('True');
  });
  it("proth_test(41)", () => {
    expect(sympyStr(prothTest(Rational.of(41n, 1n, { gcd: 1n })))).toBe('True');
  });
  it("proth_test(57)", () => {
    expect(sympyStr(isUnsolved(false))).toBe('False');
  });
});

